#!/bin/sh
# The workload for claim E7.7: a job of N trivial steps, which is what `GOGC` was chosen for (the
# engine allocates per exec, so step-heavy jobs are where its garbage collector shows). Every step's
# script carries the trial's token, so no step is replayed and each trial measures real work.
#
# Usage: gen-workflow.sh [N] > measure-steps.yml
set -eu
n=${1:-40}
cat <<'HEAD'
# Generated by measurements/e7.7/gen-workflow.sh — do not edit by hand.
name: measure-steps
on:
  workflow_dispatch:
    inputs:
      token:
        description: A value new for every trial, so no step can be replayed
        required: true
jobs:
  steps:
    runs-on: [self-hosted, zig]
    steps:
HEAD
i=1
while [ "$i" -le "$n" ]; do
  # Double-quoted, so the ": " inside is a quoted scalar and not a mapping (check-workflows).
# shellcheck disable=SC2016  # the workflow needs a literal ${{ }} for GitHub to expand
  printf '      - run: ": step %s of %s, trial ${{ inputs.token }}"\n' "$i" "$n"
  i=$((i + 1))
done
